CREATE TABLE IF NOT EXISTS "exam_hubs" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "name" text NOT NULL, "education_level" text NOT NULL, "school_name" text NOT NULL DEFAULT '', "grade" integer NOT NULL, "exam_number" text NOT NULL, "open_at" timestamptz, "close_at" timestamptz, "status" text NOT NULL DEFAULT 'draft', "announcement" text NOT NULL DEFAULT '', "show_marquee" boolean NOT NULL DEFAULT false, "created_by" uuid REFERENCES "users"("id") ON DELETE SET NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "exam_hubs_match_idx" ON "exam_hubs" ("education_level", "school_name", "grade", "status"); CREATE INDEX IF NOT EXISTS "exam_hubs_window_idx" ON "exam_hubs" ("open_at", "close_at");
CREATE TABLE IF NOT EXISTS "exam_hub_words" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "hub_id" uuid NOT NULL REFERENCES "exam_hubs"("id") ON DELETE CASCADE, "word" text NOT NULL, "normalized_word" text NOT NULL, "meaning" text NOT NULL DEFAULT '', "part_of_speech" text NOT NULL DEFAULT '', "synonyms" jsonb NOT NULL DEFAULT '[]', "antonyms" jsonb NOT NULL DEFAULT '[]', "collocations" jsonb NOT NULL DEFAULT '[]', "phrases" jsonb NOT NULL DEFAULT '[]', "example" text NOT NULL DEFAULT '', "example_zh" text NOT NULL DEFAULT '', "phonetic" text NOT NULL DEFAULT '', "audio_url" text NOT NULL DEFAULT '', "published" boolean NOT NULL DEFAULT true, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "exam_hub_words_uq" ON "exam_hub_words" ("hub_id", "normalized_word"); CREATE INDEX IF NOT EXISTS "exam_hub_words_hub_idx" ON "exam_hub_words" ("hub_id", "published");
CREATE TABLE IF NOT EXISTS "exam_hub_word_progress" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "hub_word_id" uuid NOT NULL REFERENCES "exam_hub_words"("id") ON DELETE CASCADE, "user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "familiarity" integer NOT NULL DEFAULT 0, "wrong_count" integer NOT NULL DEFAULT 0, "review_count" integer NOT NULL DEFAULT 0, "last_reviewed_at" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "exam_hub_word_progress_uq" ON "exam_hub_word_progress" ("hub_word_id", "user_id"); CREATE INDEX IF NOT EXISTS "exam_hub_word_progress_user_idx" ON "exam_hub_word_progress" ("user_id", "updated_at");
CREATE TABLE IF NOT EXISTS "exam_hub_attempts" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "hub_id" uuid NOT NULL REFERENCES "exam_hubs"("id") ON DELETE CASCADE, "user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "mode" text NOT NULL, "direction" text NOT NULL DEFAULT 'en2zh', "score" integer NOT NULL DEFAULT 0, "total" integer NOT NULL DEFAULT 0, "responses" jsonb NOT NULL DEFAULT '{}', "wrong_word_ids" jsonb NOT NULL DEFAULT '[]', "created_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "exam_hub_attempts_user_idx" ON "exam_hub_attempts" ("user_id", "created_at"); CREATE INDEX IF NOT EXISTS "exam_hub_attempts_hub_idx" ON "exam_hub_attempts" ("hub_id", "created_at");
